import 'dart:convert';
import 'package:graph_explorer/graph_explorer.dart';

void main() async {
  var graph = Graph<String>();
  graph.node('a').getOrAddOutput('b').addOutput('c');
  var result = await graph.scanPathsFrom('a', 'c', findAll: true);
  for (var p in result.paths) {
    print(p.toListOfString());
  }
}
